import{escapeHTML}from"./utils.js";

const rect=(x,y,w,h,fill,extra="")=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${fill}" ${extra}/>`;
function coreShape(v){const b=v.blueprint,p=v.primaryColor,s=v.secondaryColor,a=v.accentColor,w=Math.round(48*b.width),h=Math.round(50*b.height),x=Math.round(64-w/2),y=Math.round(65-h/2);let out="";for(let i=0;i<b.coreCount;i++){const ox=b.symmetry==="lopsided"?i*8:(i-(b.coreCount-1)/2)*11,oy=b.symmetry==="stacked"?-i*13:(i%2)*6,ww=Math.max(18,w-i*6),hh=Math.max(20,h-i*4);if(["spiral","coil","orbit"].includes(b.coreShape))out+=`<path d="M${x+ox} ${y+oy+hh/2}h${ww}v${hh/2}H${x+ox+7}V${y+oy+8}h${ww-14}v${hh-16}H${x+ox+15}v-${Math.max(7,hh-28)}h${Math.max(10,ww-30)}" fill="none" stroke="${i%2?p:s}" stroke-width="8"/>`;else if(["tangle","crescent"].includes(b.coreShape))out+=`<path d="M${x+ox+4} ${y+oy+hh*.2}Q${x+ox+ww*.8} ${y+oy-8} ${x+ox+ww} ${y+oy+hh*.45}T${x+ox+9} ${y+oy+hh}Q${x+ox-8} ${y+oy+hh*.5} ${x+ox+4} ${y+oy+hh*.2}Z" fill="${i%2?s:p}" stroke="#120f1b" stroke-width="4"/>`;else if(b.coreShape==="arch")out+=`<path d="M${x+ox} ${y+oy+hh}V${y+oy+hh*.42}Q${x+ox+ww/2} ${y+oy-8} ${x+ox+ww} ${y+oy+hh*.42}V${y+oy+hh}H${x+ox+ww*.72}V${y+oy+hh*.5}Q${x+ox+ww/2} ${y+oy+hh*.26} ${x+ox+ww*.28} ${y+oy+hh*.5}V${y+oy+hh}Z" fill="${p}" stroke="#120f1b" stroke-width="4"/>`;else out+=`<path d="M${x+ox+8} ${y+oy}h${ww-16}v7h8v${hh-14}h-8v7H${x+ox+7}v-7H${x+ox}V${y+oy+8}h8Z" fill="${i%2?s:p}" stroke="#120f1b" stroke-width="4"/>`}if(b.material==="paper")out+=`<path d="M${x+8} ${y+15}h${w-18}M${x+10} ${y+28}h${w-27}" stroke="${a}" stroke-width="3"/>`;if(b.material==="glitch")out+=`${rect(x-8,y+18,22,6,a)}${rect(x+w-9,y+h-23,23,7,a)}`;if(b.material==="glass")out+=rect(x+8,y+8,Math.max(9,w*.25),Math.max(14,h*.55),"#fff",'opacity=".24"');return out}
function limbs(v){const b=v.blueprint,s=v.secondaryColor;let out="";for(let i=0;i<(v.arms||0)/2;i++){const y=49+i*13;out+=`<path d="M37 ${y}H${18-i*3}v${i%2?12:-9}H${9-i*2}M91 ${y}h${19+i*3}v${i%2?12:-9}h${9+i*2}" fill="none" stroke="${s}" stroke-width="5"/>`}for(let i=0;i<(v.legs||0)/2;i++){const x=49+i*29;out+=`<path d="M${x} 94v17h${i%2?10:-10}" fill="none" stroke="${s}" stroke-width="6"/>`}if(b.locomotion==="wheels")out+=`<circle cx="46" cy="104" r="9" fill="#171221" stroke="${v.accentColor}" stroke-width="4"/><circle cx="82" cy="104" r="9" fill="#171221" stroke="${v.accentColor}" stroke-width="4"/>`;if(b.locomotion==="tendrils")out+=`<path d="M42 91q-25 16-13 31m35-31q-9 24 3 34m18-34q25 15 15 31" fill="none" stroke="${s}" stroke-width="5"/>`;return out}
function face(v,damage){const b=v.blueprint,count=Math.min(6,Math.max(1,v.eyes||2)),positions=[[49,53],[79,53],[64,40],[37,68],[91,68],[64,72]],dy=b.facePlacement==="high"?-9:b.facePlacement==="low"?10:0;let out=positions.slice(0,count).map(([x,y])=>`${rect(x-7,y-6+dy,14,damage>65?7:15,"#fff8dc")}${rect(x+(damage>70?2:-2),y-2+dy,5,damage>65?5:8,"#171221")}`).join("");const my=79+dy;if(v.mouth==="crooked")out+=`<path d="M45 ${my}h18v5h26" fill="none" stroke="#171221" stroke-width="6"/>`;else if(v.mouth==="huge")out+=`<rect x="35" y="${my-8}" width="58" height="27" fill="#171221"/><path d="M40 ${my-5}h48l-7 8-7-8-7 8-8-8-7 8-7-8Z" fill="#fff8dc"/>`;else out+=damage>72?`<path d="M47 ${my+7}v-5h35v5" fill="none" stroke="#171221" stroke-width="5"/>`:`<path d="M46 ${my}h39v-6" fill="none" stroke="#171221" stroke-width="5"/>`;return out}
function primitive(part,i,color){const x=15+(i%4)*29,y=18+Math.floor(i/4)*77;const known={mask:`<path d="M38 42h52v25L76 78H53L38 67Z" fill="#f4ead9" opacity=".76" stroke="#171221" stroke-width="3"/>`,spotlight:`<path d="M18 2h28l31 95H43Z" fill="${color}" opacity=".2"/>${rect(16,2,32,9,color)}`,screen:`${rect(36,28,57,40,"#17152b",`stroke="${color}" stroke-width="4"`)}${rect(44,37,36,5,color)}`,medals:`${rect(51,92,9,12,color)}${rect(68,92,9,12,color)}<circle cx="55" cy="108" r="7" fill="#ffd84d"/><circle cx="73" cy="108" r="7" fill="#ffd84d"/>`,strings:`<path d="M34 4v39m30-39v35m29-35v39" stroke="#eee6f4" stroke-width="2" stroke-dasharray="4 3"/>`,manyEyes:`${rect(15,90,10,8,"#fff")}${rect(46,101,10,8,"#fff")}${rect(96,92,10,8,"#fff")}`,rankboard:`${rect(8,12,39,24,"#17152b",`stroke="${color}" stroke-width="3"`)}<text x="15" y="28" fill="${color}" font-size="10" font-weight="900">#02</text>`,closedDoor:`${rect(42,18,45,83,"#30274d",'stroke="#171221" stroke-width="5"')}${rect(75,59,5,5,color)}`,manyArms:`<path d="M32 52H7v-9m25 28H3v10m93-30h27v-9M96 72h29v11" fill="none" stroke="${color}" stroke-width="5"/>`,remote:`${rect(91,27,23,40,"#222034",`stroke="${color}" stroke-width="3"`)}<circle cx="102" cy="38" r="4" fill="${color}"/>`,clock:`${rect(47,15,35,30,"#fff8dc",'stroke="#171221" stroke-width="3"')}${rect(63,20,4,12,"#171221")}${rect(64,31,10,4,"#171221")}`,needles:`<path d="m18 43-15-8 15-4m92 20 15-8-15-4M24 91 7 99m96-9 18 9" stroke="${color}" stroke-width="4"/>`,flames:`<path d="M29 31Q18 13 32 4m65 29q13-17 1-28M17 73Q2 60 11 47" fill="none" stroke="${color}" stroke-width="5"/>`,repeat:`<text x="8" y="120" fill="${color}" font-size="12" font-weight="900">AGAIN AGAIN</text>`};return known[part]||`${rect(x,y,16,10,color,`transform="rotate(${i%2?8:-8} ${x+8} ${y+5})"`)}<path d="M${x+3} ${y+3}h10" stroke="#171221" stroke-width="2"/>`}
function armorSVG(armor,v){return armor.filter(x=>x.state!=="broken").map((item,i)=>`<g class="symbolic-armor armor-${i}" data-armor="${escapeHTML(item.id)}">${primitive(item.trait||"mask",i,v.accentColor)}<title>${escapeHTML(item.label)}</title></g>`).join("")}
export function monsterSVG(encounter,{damage=0,armor=encounter.symbolicArmorDNA,core=false}={}){const v=encounter.monsterDNA.visual;return`<svg class="monster-svg" viewBox="0 0 128 128" role="img" aria-label="${escapeHTML(encounter.monsterDNA.name)}" shape-rendering="crispEdges"><g class="monster-core">${limbs(v)}${coreShape(v)}${face(v,damage)}${v.blueprint.anchorParts.map((p,i)=>primitive(p,i,v.accentColor)).join("")}${armorSVG(armor,v)}${core?`<g class="core-reveal"><rect x="52" y="49" width="24" height="24" fill="#fff9e9" stroke="${v.accentColor}" stroke-width="5"/><circle cx="64" cy="61" r="5" fill="#171221"/></g>`:""}</g></svg>`}
export function renderMonster(root,encounter,combat){const el=document.createElement("div"),mutation=encounter.mutationDNA||[],scale=encounter.monsterDNA.visual.blueprint.scale*(mutation.some(x=>x.id==="giant")?1.24:mutation.some(x=>x.id==="mini")?0.78:1);el.className="monster-wrap idle target";el.dataset.move=encounter.monsterDNA.visual.blueprint.motion;el.dataset.phase=combat.phase;el.style.setProperty("--scale",String(scale));el.innerHTML=monsterSVG(encounter,{damage:0,armor:combat.armor});root.appendChild(el);const clones=mutation.some(x=>x.id==="clone")?2:0;for(let i=0;i<clones;i++){const c=el.cloneNode(true);c.classList.add("false-clone");c.style.setProperty("--clone",String(i?1:-1));root.appendChild(c)}return el}
export function updateMonster(el,encounter,combat){if(!el)return;const damage=Math.round((1-combat.hp/combat.maxHp)*100);el.dataset.phase=combat.phase;el.classList.toggle("core-visible",Boolean(encounter.storyDNA.coreReveal&&combat.phase==="BREAKDOWN"));el.innerHTML=monsterSVG(encounter,{damage,armor:combat.armor,core:encounter.storyDNA.coreReveal&&combat.phase==="BREAKDOWN"})}
